import{_ as a,o as e,c as r,a0 as o}from"./chunks/framework.DwEC4Wzn.js";const p=JSON.parse('{"title":"功能详解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":null}'),i={name:"guide/features.md"};function l(d,t,n,s,h,u){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="功能详解" tabindex="-1">功能详解 <a class="header-anchor" href="#功能详解" aria-label="Permalink to &quot;功能详解&quot;">​</a></h1><h2 id="满电静置自动限充" tabindex="-1">满电静置自动限充 <a class="header-anchor" href="#满电静置自动限充" aria-label="Permalink to &quot;满电静置自动限充&quot;">​</a></h2><p>笔记本<strong>电量充满</strong>（≥95%，照顾标定偏差到不了 100% 的旧电池）后继续插电超过设定时长 （默认 <strong>30 分钟</strong>）时，自动把充电阈值设为 <strong>75%–80%</strong>：电量到 80% 停止充电，低于 75% 才重新充电，与联想 Vantage 的「自定义阈值」一致。拔掉电源自动恢复默认（不限制）。</p><table tabindex="0"><thead><tr><th>场景</th><th>行为</th></tr></thead><tbody><tr><td>充满后插电达到设定时长</td><td>下发充电阈值 75%–80%（计时从满电那一刻起，掉到 95% 以下或拔电即作废）</td></tr><tr><td>电量未充满</td><td>不限充，状态行显示「已插电，等待电量充满（充满后开始计时）」</td></tr><tr><td>拔掉电源</td><td>恢复默认充电策略；重新插电重新计时</td></tr><tr><td>临时解除限充</td><td>立即恢复默认，本次插电不再自动限制；<strong>重新充满电或拔掉电源后</strong>自动恢复管理（跨重启保留，防止忘记改回）</td></tr><tr><td>立即启用限充</td><td>手动立即生效，并取消临时解除状态</td></tr><tr><td>未检测到联想电源管理驱动</td><td>无法控制阈值，设置页会有红色提示</td></tr></tbody></table><p>设置页可调：充电上限（默认 80%，范围 50–100）、生效时长（默认 30 分钟，范围 5–720）、 拔电是否恢复、开机自启。改完即存，配置写在 <code>HKCU\\Software\\PowerKit</code>。</p><p>满电静置的计时<strong>跨重启保留</strong>：重启后仍从当初充满的那一刻起算，不会因为重启而重新计时。</p><h2 id="仪表盘" tabindex="-1">仪表盘 <a class="header-anchor" href="#仪表盘" aria-label="Permalink to &quot;仪表盘&quot;">​</a></h2><ul><li>电量与充放电状态；</li><li>电源功率：由电压 × 电流算出，正数表示充电、负数表示放电；</li><li>电池健康：满充容量 / 设计容量、循环次数、温度。</li></ul><h2 id="摄像头感光自动亮度" tabindex="-1">摄像头感光自动亮度 <a class="header-anchor" href="#摄像头感光自动亮度" aria-label="Permalink to &quot;摄像头感光自动亮度&quot;">​</a></h2><p>用前置摄像头当环境光传感器，不需要机器自带光线感应器：</p><ul><li>环境光读数取连续几帧的中位数，去掉两端 10% 的极端像素，避免一帧噪点或屏幕反光带偏；</li><li>按感知曲线（gamma 1.2）映射到 20–100% 亮度，可整体偏移 ±20%；</li><li><strong>采样节奏自适应</strong>：环境在变时约 12 秒采一次，读数稳定后逐步退避到最长 5 分钟； 人离开屏幕（约 2 分钟无键鼠输入）期间不点亮摄像头，回到座位后立刻恢复；</li><li><strong>目标连续两次采样一致才下发</strong>（跳变 ≥25 时立即响应），死区取「至少 5% 且不小于当前值的 10%」； 确认后按每 300ms 走 1% 渐变到位——既不来回抖，也不闪一下；</li><li><strong>摄像头被遮挡或被禁用时不动亮度</strong>：环境光读数为 0 判定为镜头被物理遮挡（防窥拨片、手指、 贴纸），取不到画面判定为摄像头不可用；两种情况都保持当前亮度，设置页会注明原因，恢复后继续调节；</li><li>亮度通道自动探测：WMI 优先、DDC/CI 兜底；<strong>没有可用通道时不会开启相机采样</strong>；</li><li>机器自带光线感应器（ALS）时该功能自动停用，开关置灰，交给 Windows 自带自动亮度。</li></ul><p>相机画面只用于算一个环境光数值，不保存、不上传。</p><h2 id="键盘背光自动控制" tabindex="-1">键盘背光自动控制 <a class="header-anchor" href="#键盘背光自动控制" aria-label="Permalink to &quot;键盘背光自动控制&quot;">​</a></h2><p>按环境光「暗时开、亮时关」，会记住你手动调过的档位。依赖联想的键盘背光接口， 机型没有该接口时开关置灰并给出提示。摄像头被遮挡或不可用时，背光与屏幕亮度一样暂停调节。</p><h2 id="浅色-深色主题" tabindex="-1">浅色 / 深色主题 <a class="header-anchor" href="#浅色-深色主题" aria-label="Permalink to &quot;浅色 / 深色主题&quot;">​</a></h2><p>默认跟随系统深浅色，系统切换时实时跟随；也可以在设置页固定为浅色或深色。</p><h2 id="设置页五页签" tabindex="-1">设置页五页签 <a class="header-anchor" href="#设置页五页签" aria-label="Permalink to &quot;设置页五页签&quot;">​</a></h2><p>自动限充 / 显示 / 通用 / 状态 / 关于。一次只渲染一张卡，窗口高度按当前页内容自动适配 并平滑过渡；「关于」页显示版本号、版权与第三方组件声明。</p><h2 id="界面形态" tabindex="-1">界面形态 <a class="header-anchor" href="#界面形态" aria-label="Permalink to &quot;界面形态&quot;">​</a></h2><ul><li>无边框飞窗固定右下角，使用系统级圆角（DWM），无系统边框线；</li><li><strong>左键点击托盘图标</strong>打开飞窗，失焦自动关闭；右上角 ×、Esc 也可关闭；</li><li>右键托盘出菜单：打开 / 隐藏、立即启用限充、临时解除限充、恢复默认充电策略、退出；</li><li>单实例：重复启动 <code>powerkit.exe</code> 只会唤出已运行实例的窗口；</li><li>隐藏态工作集约 27 MB，显示态约 39 MB。</li></ul><h2 id="支持与限制" tabindex="-1">支持与限制 <a class="header-anchor" href="#支持与限制" aria-label="Permalink to &quot;支持与限制&quot;">​</a></h2><p>充电阈值目前只覆盖<strong>联想电源管理驱动</strong>的机型（近年 ThinkPad T / X / P / E 系列及部分 Legion）。华硕、戴尔等其他品牌仍在调研中。手动用 Vantage 或 BIOS 改阈值会被本工具在 下一个周期按配置覆盖——以本工具的设置为准。</p>',22)])])}const g=a(i,[["render",l]]);export{p as __pageData,g as default};
